// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool s) { ok = s; } catch { ok = false; }
        if (ok) {
            assertTrue(c.owner() == newOwner || c.owner() == c.owner());
        }
        // general rule: any successful setOwner(newOwner) makes owner() == newOwner
        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) returns (bool s) { ok2 = s; } catch { ok2 = false; }
        assertTrue(!(ok2) || c.owner() == newOwner);
    }
}

