pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address nextTarget) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(uint160(newOwner) > type(uint160).max / 2 == false); // keep default: no constraint narrowing
        vm.assume(newOwner != address(c));
        // current owner (test contract as deployer) hands ownership to the fuzzed newOwner
        c.setOwner(newOwner);
        // RULE: the newly appointed owner can exercise owner rights immediately
        vm.prank(newOwner);
        bool ok;
        try c.setOwner(nextTarget) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == nextTarget);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address mid, address finalOwner) public {
        vm.assume(mid != address(0));
        vm.assume(finalOwner != address(0));

        // current owner (the test contract) transfers ownership to `mid`
        vm.prank(address(this));
        c.setOwner(mid);

        // `mid` (now the owner) transfers ownership to `finalOwner`
        vm.prank(mid);
        c.setOwner(finalOwner);

        // General rule: a successful transfer by the current owner always sets
        // owner to the requested target. Chained transfers therefore yield
        // owner == finalOwner. The mutant rewrites owner to msg.sender inside
        // the modifier, so after the second call owner == mid, not finalOwner.
        assertTrue(c.owner() == finalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target) public {
        // Admissible domain: any target other than the current owner.
        vm.assume(target != c.owner());

        // The deployer (this test contract) is the current owner.
        vm.prank(c.owner());
        try c.setOwner(target) {
            // General rule: after an owner-issued transfer to `target`,
            // the owner is exactly `target` (for every admissible target).
            assertTrue(c.owner() == target);
        } catch {
            // A legitimate owner transfer to an admissible target must not revert.
            assertTrue(false);
        }
    }
}
